// Texts, Google Sheet column names and node names used below. Edit the texts here.
const T = {
  "locale": "en-US",
  "nodes": {
    "config": "Config",
    "readLeads": "Read leads"
  },
  "cols": {
    "lead": {
      "id": "Lead ID",
      "lastEnquiry": "Last Enquiry At",
      "name": "Name",
      "email": "Email",
      "phone": "Phone",
      "intent": "Intent",
      "propertyRef": "Property Ref",
      "budget": "Budget",
      "timeline": "Timeline",
      "areas": "Preferred Areas",
      "minBeds": "Min Bedrooms",
      "propertyType": "Property Type",
      "message": "Message",
      "source": "Source",
      "score": "Score",
      "temperature": "Temperature",
      "status": "Status",
      "step": "Follow-up Step",
      "lastContact": "Last Contact At",
      "nextFollowUp": "Next Follow-up At",
      "notes": "Notes",
      "repliedAt": "Replied At"
    }
  },
  "values": {
    "intent": {
      "buy": "buy",
      "sell": "sell",
      "rent": "rent",
      "other": "other"
    },
    "timeline": {
      "soon": "0-3 months",
      "mid": "3-6 months",
      "later": "6+ months",
      "unknown": "unknown"
    },
    "temp": {
      "hot": "Hot",
      "warm": "Warm",
      "cold": "Cold"
    },
    "leadStatus": {
      "new": "New",
      "contacted": "Contacted",
      "replied": "Replied",
      "unsubscribed": "Unsubscribed"
    },
    "listingStatus": {
      "available": "Available"
    },
    "listingType": {
      "sale": "Sale",
      "rent": "Rent"
    },
    "viewingStatus": {
      "booked": "Booked",
      "done": "Done",
      "cancelled": "Cancelled"
    }
  },
  "text": {
    "followup": {
      "subjects": {
        "buy": [
          "Still looking? I have a few homes that could suit you",
          "New on the market this week",
          "Is now still the right time to move?",
          "Shall I keep you on my list?"
        ],
        "sell": [
          "Your property valuation — any questions?",
          "What homes like yours sold for recently",
          "Thinking about timing your sale?",
          "Shall I keep you updated on local prices?"
        ],
        "rent": [
          "Still searching for a rental?",
          "New rentals that just became available",
          "Can I help you find the right place?",
          "Shall I keep sending you rentals?"
        ]
      },
      "bodies": {
        "buy": [
          "I wanted to check in after your enquiry. If you let me know your budget and must-haves, I can send you a short list of homes that match.",
          "A few new homes came to market this week. Reply with \"send them\" and I will email you the ones that fit your criteria.",
          "Moving plans often change — if your timeline has shifted, just let me know and I will adjust what I send you.",
          "I do not want to fill your inbox. Reply \"yes\" if you would like me to keep you informed, otherwise I will stop here."
        ],
        "sell": [
          "Following up on your valuation request. Happy to answer any questions about the process, fees or timing.",
          "Several similar homes in your area sold recently. I can share the prices and how quickly they sold.",
          "Spring and early autumn are usually strong selling periods. Shall we plan the right moment for your sale?",
          "Reply \"yes\" if you would like occasional updates on local prices, otherwise I will stop here."
        ],
        "rent": [
          "Just checking whether you are still looking for a rental. Tell me your move-in date and budget and I will shortlist options.",
          "New rentals are coming in — reply with your preferred areas and I will send the best matches.",
          "Good rentals go quickly. Want me to arrange viewings as soon as something suitable is listed?",
          "Reply \"yes\" to keep receiving rentals, otherwise I will stop here."
        ]
      },
      "greeting": "<p>Hi {firstName},</p>",
      "greetingNoName": "<p>Hi there,</p>",
      "bookLine": "<p>You can also book a quick call here: {booking}</p>",
      "stopPattern": "\\bstop\\b|unsubscribe|remove me|not interested",
      "quoteMarkers": "\\bOn .{0,120}wrote:|-----Original|________________|\\nFrom: ",
      "digestSubject": "Follow-ups {date}: {replied} replied, {sent} sent",
      "digestReplied": "<p><b>They replied: call them back ({n})</b></p><ul>{items}</ul>",
      "digestUnsub": "<p><b>Asked to stop ({n})</b>, now marked Unsubscribed</p><ul>{items}</ul>",
      "digestSent": "<p><b>Follow-ups sent today ({n})</b></p><ul>{items}</ul>",
      "digestNext": "<p>Due on the next run ({date}): <b>{n}</b></p>",
      "digestReplyItem": "<li><b>{name}</b> ({email}), {when}: <i>{text}</i></li>",
      "digestSentItem": "<li>{name} ({email}), email {step}</li>",
      "dateFormat": "ccc d LLL",
      "timeFormat": "ccc d LLL, HH:mm",
      "signature": "<p>Best regards,<br>{agentName}<br>{agency}</p>"
    }
  }
};

// Plan today's run: leads who replied leave the sequence, the others get their next follow-up if it is due,
// and one summary goes to the agent. Input = the Gmail search results; the leads come from the "Read leads" node.
// Helpers (texts and column names live in the T object above — edit them there).
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fill = (tpl, vars) => String(tpl).replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? vars[k] : m));
const greet = (tpl, name) => (String(name || '').trim()
  ? fill(tpl.greeting, { firstName: esc(String(name).trim().split(' ')[0]) })
  : tpl.greetingNoName);
// Internal key from a cell value: accepts the key itself ("buy") or the label of this language ("Buy", "achat").
const keyOf = (map, label) => {
  const l = String(label ?? '').trim().toLowerCase();
  for (const [k, v] of Object.entries(map)) if (l === k || l === String(v).toLowerCase()) return k;
  return null;
};
const money = (n) => new Intl.NumberFormat(T.locale, { maximumFractionDigits: 0 }).format(n);
const isEmail = (v) => /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(v || '').trim());
const config = $(T.nodes.config).first().json;
const C = T.cols.lead;
const X = T.text.followup;
const S = T.values.leadStatus;
const now = DateTime.now();
const today = now.startOf('day');

// "1,3,7,14" = days after the first contact -> gaps between consecutive follow-ups.
const offsets = String(config.followUpDays).split(',').map((d) => parseInt(d, 10)).filter((d) => d > 0);
const gaps = offsets.map((d, i) => d - (i ? offsets[i - 1] : 0));
const stopStatuses = String(config.stopStatuses).split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const holidays = String(config.holidays || '').split(',').map((s) => s.trim()).filter(Boolean);
const maxPerRun = Number(config.maxEmailsPerRun) || 50;
const parseDate = (v) => {
  if (!v) return null;
  const d = DateTime.fromISO(String(v));
  return d.isValid ? d : null;
};
// Calendar day in the workflow time zone: delays count in days, not elapsed hours.
const dayOf = (d) => d.setZone(now.zone).startOf('day');
const vars = {
  booking: `<a href="${esc(config.bookingLink)}">${esc(config.bookingLink)}</a>`,
  agentName: esc(config.agentName), agency: esc(config.agencyName),
};

// --- 1. Replies found in Gmail ---
// Replies found by the Gmail search (input of this node), by sender address. Works with the simplified or the full
// output of the Gmail node, and keeps only the sender's own words: the quoted copy of our email contains "Reply STOP".
// Needs X.quoteMarkers, X.stopPattern and parseDate. Same file in both kits (checked by a test).
const addressOf = (v) => (String(v || '').match(/[^\s<>"',;:]+@[^\s<>"',;:]+\.[a-z]{2,}/i) || [''])[0].toLowerCase();
const quoteRe = new RegExp(X.quoteMarkers, 'i');
const stopRe = new RegExp(X.stopPattern, 'i');
const replies = {};
for (const item of $input.all()) {
  const m = item.json || {};
  const from = addressOf(m.From || (m.from && (m.from.text || (m.from.value || [])[0]?.address)) || '');
  const at = m.internalDate ? DateTime.fromMillis(Number(m.internalDate)) : parseDate(m.date);
  if (!from || !at || !at.isValid) continue;
  const text = String(m.snippet ?? m.text ?? '');
  const cut = text.search(quoteRe);
  const own = (cut >= 0 ? text.slice(0, cut) : text).replace(/\s+/g, ' ').trim();
  (replies[from] = replies[from] || []).push({ at, own });
}
// Latest reply from `email` received after `since` (2-minute margin, so a request sent by email never counts),
// with `stop` = the sender asks not to be emailed again.
const replyAfter = (email, since) => {
  if (!since) return null;
  const found = (replies[String(email).toLowerCase()] || []).filter((r) => r.at > since.plus({ minutes: 2 }));
  if (!found.length) return null;
  const latest = found.reduce((a, b) => (b.at > a.at ? b : a));
  return { ...latest, stop: stopRe.test(latest.own.slice(0, 120)) };
};

// --- 2. Each lead: replied -> out of the sequence, otherwise the next follow-up if it is due ---
let nextRun = today.plus({ days: 1 });
while (nextRun.weekday > 5 || holidays.includes(nextRun.toISODate())) nextRun = nextRun.plus({ days: 1 });
const out = [];
const sent = [];
const replied = [];
const unsub = [];
let dueNext = 0;
for (const item of $(T.nodes.readLeads).all()) {
  const row = item.json;
  const email = String(row[C.email] || '').trim();
  const status = String(row[C.status] || '').trim().toLowerCase();
  if (!isEmail(email) || stopStatuses.includes(status)) continue;

  // A reply = a message from the lead received after their enquiry.
  const answer = replyAfter(email, parseDate(row[C.lastEnquiry]) || parseDate(row[C.lastContact]));
  if (answer) {
    const update = {};
    update[C.id] = row[C.id];
    update[C.status] = answer.stop ? S.unsubscribed : S.replied;
    update[C.repliedAt] = answer.at.toISO();
    update[C.nextFollowUp] = '';
    out.push({ json: { kind: 'replied', update } });
    (answer.stop ? unsub : replied).push({ name: row[C.name], email, at: answer.at, own: answer.own });
    continue;
  }

  const step = parseInt(row[C.step], 10) || 0;
  if (step >= gaps.length) continue;
  const last = parseDate(row[C.lastContact]) || parseDate(row[C.lastEnquiry]);
  if (!last) continue;
  if (today.diff(dayOf(last), 'days').days < gaps[step] || sent.length >= maxPerRun) {
    if (nextRun.diff(dayOf(last), 'days').days >= gaps[step]) dueNext += 1;
    continue;
  }

  const intentKey = keyOf(T.values.intent, row[C.intent]);
  const intent = ['buy', 'sell', 'rent'].includes(intentKey) ? intentKey : 'buy';
  const tpl = Math.min(step, X.subjects[intent].length - 1);
  const nextGap = gaps[step + 1];
  const isNew = status === '' || keyOf(S, status) === 'new';
  const update = {};
  update[C.id] = row[C.id];
  update[C.step] = step + 1;
  update[C.lastContact] = now.toISO();
  update[C.nextFollowUp] = nextGap ? now.plus({ days: nextGap }).toISODate() : '';
  update[C.status] = isNew ? S.contacted : row[C.status];
  out.push({
    json: {
      kind: 'followup',
      email: {
        to: email,
        subject: X.subjects[intent][tpl],
        html: `${greet(X, row[C.name])}<p>${X.bodies[intent][tpl]}</p>
${fill(X.bookLine, vars)}
${fill(X.signature, vars)}
<p style="font-size:12px;color:#888">${esc(config.unsubscribeText)}</p>`,
      },
      update,
    },
  });
  sent.push({ name: row[C.name], email, step: step + 1 });
  if (nextGap && nextRun.diff(today, 'days').days >= nextGap) dueNext += 1;
}

// --- 3. One summary for the agent, only when something happened ---
const fmtDay = (d) => d.setLocale(T.locale).toFormat(X.dateFormat);
const list = (rows, tpl) => rows.map((r) => fill(tpl, {
  name: esc(r.name || r.email), email: esc(r.email), step: r.step,
  when: r.at ? esc(r.at.setZone(now.zone).setLocale(T.locale).toFormat(X.timeFormat)) : '',
  text: esc(String(r.own || '').slice(0, 160)),
})).join('');
const wantDigest = String(config.dailyDigest).toLowerCase() !== 'false';
if (wantDigest && isEmail(config.agentEmail) && (sent.length || replied.length || unsub.length)) {
  const parts = [];
  if (replied.length) parts.push(fill(X.digestReplied, { n: replied.length, items: list(replied, X.digestReplyItem) }));
  if (unsub.length) parts.push(fill(X.digestUnsub, { n: unsub.length, items: list(unsub, X.digestReplyItem) }));
  if (sent.length) parts.push(fill(X.digestSent, { n: sent.length, items: list(sent, X.digestSentItem) }));
  parts.push(fill(X.digestNext, { date: esc(fmtDay(nextRun)), n: dueNext }));
  out.push({
    json: {
      kind: 'digest',
      email: {
        to: String(config.agentEmail).trim(),
        subject: fill(X.digestSubject, { date: fmtDay(today), replied: replied.length + unsub.length, sent: sent.length }),
        html: parts.join('\n'),
      },
    },
  });
}
return out;
